CREATE TABLE IF NOT EXISTS public.subcontrato_avances (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, fecha DATE NOT NULL, partida_nombre TEXT NOT NULL, cantidad NUMERIC NOT NULL CHECK(cantidad>=0), unidad TEXT, comentario TEXT, estado TEXT NOT NULL DEFAULT 'Reportado', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subcontrato_asistencia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, fecha DATE NOT NULL, presentes INTEGER NOT NULL CHECK(presentes>=0), ausentes INTEGER DEFAULT 0 CHECK(ausentes>=0), horas_hombre NUMERIC DEFAULT 0 CHECK(horas_hombre>=0), estado TEXT NOT NULL DEFAULT 'Reportado', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subcontrato_estados_pago (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subcontrato_id BIGINT NOT NULL, subcontrato_nombre TEXT NOT NULL, empresa TEXT NOT NULL, obra_nombre TEXT NOT NULL, numero INTEGER NOT NULL, periodo_desde DATE NOT NULL, periodo_hasta DATE NOT NULL, monto_presentado NUMERIC NOT NULL CHECK(monto_presentado>=0), monto_aprobado NUMERIC, factura_folio TEXT, factura_url TEXT, observaciones TEXT, estado TEXT NOT NULL DEFAULT 'Presentado', aprobado_por TEXT, aprobado_at TIMESTAMPTZ, costo_real_id BIGINT, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(subcontrato_id,obra_nombre,numero));
CREATE TABLE IF NOT EXISTS public.costos_reales_obra (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, obra_nombre TEXT NOT NULL, nombre TEXT NOT NULL, tipo_costo TEXT, asociar_factura BOOLEAN DEFAULT false, num_factura TEXT, monto NUMERIC NOT NULL DEFAULT 0, imputaciones JSONB DEFAULT '[]', empresa TEXT, origen TEXT, origen_id BIGINT UNIQUE, created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE public.subcontrato_avances ENABLE ROW LEVEL SECURITY; ALTER TABLE public.subcontrato_asistencia ENABLE ROW LEVEL SECURITY; ALTER TABLE public.subcontrato_estados_pago ENABLE ROW LEVEL SECURITY; ALTER TABLE public.costos_reales_obra ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['subcontrato_avances','subcontrato_asistencia','subcontrato_estados_pago','costos_reales_obra'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I','empresa_interna_select',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND (u.empresa=%I.empresa OR lower(u.empresa)=''obraxis'')))','empresa_interna_select',t,t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(p_estado_pago_id BIGINT,p_aprobado_por TEXT) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ep public.subcontrato_estados_pago; cid BIGINT; BEGIN SELECT * INTO ep FROM public.subcontrato_estados_pago WHERE id=p_estado_pago_id FOR UPDATE; IF ep.id IS NULL THEN RAISE EXCEPTION 'Estado de pago no encontrado'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin') OR lower(coalesce(u.rol,'')) LIKE '%admin%' OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.aprobar_pago')) THEN RAISE EXCEPTION 'Tu rol no tiene permiso para aprobar estados de pago de subcontratos'; END IF; IF coalesce(ep.factura_folio,'')='' THEN RAISE EXCEPTION 'Debe existir una factura asociada'; END IF; INSERT INTO public.costos_reales_obra(obra_nombre,nombre,tipo_costo,asociar_factura,num_factura,monto,empresa,origen,origen_id) VALUES(ep.obra_nombre,'Estado de pago subcontrato · '||ep.subcontrato_nombre,'Subcontrato',true,ep.factura_folio,coalesce(ep.monto_aprobado,ep.monto_presentado),ep.empresa,'Estado de pago subcontrato',ep.id) ON CONFLICT(origen_id) DO UPDATE SET monto=excluded.monto,num_factura=excluded.num_factura RETURNING id INTO cid; UPDATE public.subcontrato_estados_pago SET estado='Aprobado',monto_aprobado=coalesce(monto_aprobado,monto_presentado),aprobado_por=p_aprobado_por,aprobado_at=now(),costo_real_id=cid WHERE id=ep.id; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) TO authenticated;

-- Expediente documental de estados de pago de subcontratos.
CREATE TABLE IF NOT EXISTS public.subcontrato_ep_requisitos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  empresa TEXT NOT NULL,
  obra_nombre TEXT,
  codigo TEXT NOT NULL,
  nombre TEXT NOT NULL,
  descripcion TEXT,
  categoria TEXT NOT NULL DEFAULT 'Contractual' CHECK (categoria IN ('Legal','Laboral y previsional','Tributario','Contractual','Operacional')),
  fundamento TEXT,
  obligatorio BOOLEAN NOT NULL DEFAULT TRUE,
  requiere_vigencia BOOLEAN NOT NULL DEFAULT FALSE,
  activo BOOLEAN NOT NULL DEFAULT TRUE,
  orden INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (empresa, obra_nombre, codigo)
);

CREATE TABLE IF NOT EXISTS public.subcontrato_ep_documentos (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  estado_pago_id BIGINT NOT NULL REFERENCES public.subcontrato_estados_pago(id) ON DELETE CASCADE,
  requisito_id BIGINT NOT NULL REFERENCES public.subcontrato_ep_requisitos(id),
  archivo_nombre TEXT NOT NULL,
  archivo_path TEXT NOT NULL,
  mime_type TEXT,
  tamano_bytes BIGINT CHECK (tamano_bytes IS NULL OR tamano_bytes >= 0),
  periodo_desde DATE,
  periodo_hasta DATE,
  version INTEGER NOT NULL DEFAULT 1,
  estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK (estado IN ('Pendiente','Aprobado','Observado','Rechazado')),
  observacion_revision TEXT,
  cargado_por TEXT,
  revisado_por TEXT,
  revisado_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (estado_pago_id, requisito_id)
);

CREATE TABLE IF NOT EXISTS public.subcontrato_ep_historial (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  estado_pago_id BIGINT NOT NULL REFERENCES public.subcontrato_estados_pago(id) ON DELETE CASCADE,
  documento_id BIGINT REFERENCES public.subcontrato_ep_documentos(id) ON DELETE SET NULL,
  accion TEXT NOT NULL,
  estado_origen TEXT,
  estado_destino TEXT,
  detalle TEXT,
  actor_nombre TEXT,
  actor_rut TEXT,
  actor_cargo TEXT,
  actor_empresa TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.subcontrato_ep_requisitos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subcontrato_ep_documentos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subcontrato_ep_historial ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ep_requisitos_empresa ON public.subcontrato_ep_requisitos;
CREATE POLICY ep_requisitos_empresa ON public.subcontrato_ep_requisitos FOR ALL TO authenticated
USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis')))
WITH CHECK (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis')));

DROP POLICY IF EXISTS ep_documentos_empresa ON public.subcontrato_ep_documentos;
CREATE POLICY ep_documentos_empresa ON public.subcontrato_ep_documentos FOR ALL TO authenticated
USING (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')))
WITH CHECK (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')));

DROP POLICY IF EXISTS ep_historial_empresa ON public.subcontrato_ep_historial;
CREATE POLICY ep_historial_empresa ON public.subcontrato_ep_historial FOR ALL TO authenticated
USING (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_historial.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')))
WITH CHECK (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_historial.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')));

GRANT SELECT, INSERT, UPDATE, DELETE ON public.subcontrato_ep_requisitos, public.subcontrato_ep_documentos, public.subcontrato_ep_historial TO authenticated;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated;

