CREATE OR REPLACE FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(p_estado_pago_id BIGINT,p_aprobado_por TEXT) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ep public.subcontrato_estados_pago; cid BIGINT; faltantes INTEGER;
BEGIN
 SELECT * INTO ep FROM public.subcontrato_estados_pago WHERE id=p_estado_pago_id FOR UPDATE;
 IF ep.id IS NULL THEN RAISE EXCEPTION 'Estado de pago no encontrado'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=auth.uid() AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin') OR lower(coalesce(u.rol,'')) LIKE '%admin%' OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.aprobar')) THEN RAISE EXCEPTION 'Tu rol no tiene permiso para aprobar estados de pago de subcontratos'; END IF;
 SELECT count(*) INTO faltantes FROM public.subcontrato_ep_requisitos r
 WHERE r.empresa=ep.empresa AND r.activo AND r.obligatorio AND (r.obra_nombre IS NULL OR r.obra_nombre=ep.obra_nombre)
 AND NOT EXISTS (SELECT 1 FROM public.subcontrato_ep_documentos d WHERE d.estado_pago_id=ep.id AND d.requisito_id=r.id AND d.estado='Aprobado');
 IF faltantes>0 THEN RAISE EXCEPTION 'El expediente documental tiene % requisito(s) obligatorio(s) pendiente(s) de aprobación',faltantes; END IF;
 IF coalesce(ep.factura_folio,'')='' THEN RAISE EXCEPTION 'Debe existir una factura asociada'; END IF;
 INSERT INTO public.costos_reales_obra(obra_nombre,nombre,tipo_costo,asociar_factura,num_factura,monto,empresa,origen,origen_id) VALUES(ep.obra_nombre,'Estado de pago subcontrato · '||ep.subcontrato_nombre,'Subcontrato',true,ep.factura_folio,coalesce(ep.monto_aprobado,ep.monto_presentado),ep.empresa,'Estado de pago subcontrato',ep.id) ON CONFLICT(origen_id) DO UPDATE SET monto=excluded.monto,num_factura=excluded.num_factura RETURNING id INTO cid;
 UPDATE public.subcontrato_estados_pago SET estado='Aprobado',monto_aprobado=coalesce(monto_aprobado,monto_presentado),aprobado_por=p_aprobado_por,aprobado_at=now(),costo_real_id=cid WHERE id=ep.id;
 INSERT INTO public.subcontrato_ep_historial(estado_pago_id,accion,estado_origen,estado_destino,actor_nombre,actor_empresa) VALUES(ep.id,'Estado de pago aprobado',ep.estado,'Aprobado',p_aprobado_por,ep.empresa);
 RETURN cid;
END $$;
REVOKE ALL ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) TO authenticated;

-- Endurecimiento final: el historial queda inmutable para el cliente y cada
-- mutación documental exige el permiso granular correspondiente.
