DROP POLICY IF EXISTS ep_archivos_update ON storage.objects;
REVOKE ALL ON public.subcontrato_ep_requisitos, public.subcontrato_ep_documentos, public.subcontrato_ep_historial FROM authenticated;

CREATE POLICY ep_req_select ON public.subcontrato_ep_requisitos FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis')));
CREATE POLICY ep_req_insert ON public.subcontrato_ep_requisitos FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.configurar')));
CREATE POLICY ep_req_update ON public.subcontrato_ep_requisitos FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.configurar'))) WITH CHECK (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis')));
CREATE POLICY ep_req_delete ON public.subcontrato_ep_requisitos FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.usuarios u WHERE u.auth_user_id=(SELECT auth.uid()) AND (u.empresa=subcontrato_ep_requisitos.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.configurar')));

CREATE POLICY ep_doc_select ON public.subcontrato_ep_documentos FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')));
CREATE POLICY ep_doc_insert ON public.subcontrato_ep_documentos FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ?| ARRAY['obras.subcontratos.crear','obras.subcontratos.editar'])));
CREATE POLICY ep_doc_update ON public.subcontrato_ep_documentos FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis') AND (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ?| ARRAY['obras.subcontratos.editar','obras.subcontratos.revisar']))) WITH CHECK (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_documentos.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')));
CREATE POLICY ep_hist_select ON public.subcontrato_ep_historial FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.subcontrato_estados_pago ep JOIN public.usuarios u ON u.auth_user_id=(SELECT auth.uid()) WHERE ep.id=subcontrato_ep_historial.estado_pago_id AND (u.empresa=ep.empresa OR lower(u.empresa)='obraxis')));

GRANT SELECT,INSERT,UPDATE,DELETE ON public.subcontrato_ep_requisitos TO authenticated;
GRANT SELECT,INSERT,UPDATE ON public.subcontrato_ep_documentos TO authenticated;
