CREATE OR REPLACE FUNCTION public.revisar_documento_ep_subcontrato(p_documento_id BIGINT,p_estado TEXT,p_observacion TEXT DEFAULT NULL) RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE d public.subcontrato_ep_documentos; ep public.subcontrato_estados_pago; u public.usuarios; faltantes INTEGER; nuevo_estado TEXT;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sesión no autenticada'; END IF;
 IF p_estado NOT IN ('Aprobado','Observado','Rechazado') THEN RAISE EXCEPTION 'Estado de revisión no válido'; END IF;
 SELECT * INTO d FROM public.subcontrato_ep_documentos WHERE id=p_documento_id FOR UPDATE;
 SELECT * INTO ep FROM public.subcontrato_estados_pago WHERE id=d.estado_pago_id;
 SELECT * INTO u FROM public.usuarios WHERE auth_user_id=auth.uid() AND (empresa=ep.empresa OR lower(empresa)='obraxis') LIMIT 1;
 IF u.id IS NULL OR NOT (lower(coalesce(u.rol_base,'')) IN ('administrador','admin','superadmin','superusuario') OR coalesce(u.permisos,'{}'::jsonb) ? 'obras.subcontratos.revisar') THEN RAISE EXCEPTION 'Tu rol no tiene permiso para revisar documentos'; END IF;
 IF p_estado IN ('Observado','Rechazado') AND nullif(trim(coalesce(p_observacion,'')),'') IS NULL THEN RAISE EXCEPTION 'La observación es obligatoria'; END IF;
 UPDATE public.subcontrato_ep_documentos SET estado=p_estado,observacion_revision=nullif(trim(coalesce(p_observacion,'')),''),revisado_por=coalesce(u.nombre,u.usuario,u.correo),revisado_at=now(),updated_at=now() WHERE id=d.id;
 INSERT INTO public.subcontrato_ep_historial(estado_pago_id,documento_id,accion,estado_origen,estado_destino,detalle,actor_nombre,actor_rut,actor_cargo,actor_empresa) VALUES(ep.id,d.id,'Documento '||lower(p_estado),d.estado,p_estado,p_observacion,coalesce(u.nombre,u.usuario,u.correo),u.trabajador_rut,u.cargo,u.empresa);
 SELECT count(*) INTO faltantes FROM public.subcontrato_ep_requisitos r WHERE r.empresa=ep.empresa AND r.activo AND r.obligatorio AND (r.obra_nombre IS NULL OR r.obra_nombre=ep.obra_nombre) AND NOT EXISTS(SELECT 1 FROM public.subcontrato_ep_documentos x WHERE x.estado_pago_id=ep.id AND x.requisito_id=r.id AND x.estado='Aprobado');
 nuevo_estado:=CASE WHEN faltantes=0 THEN 'Expediente aprobado' WHEN p_estado IN ('Observado','Rechazado') THEN 'Documentación observada' ELSE 'Documentación en revisión' END;
 UPDATE public.subcontrato_estados_pago SET estado=nuevo_estado WHERE id=ep.id AND estado<>'Aprobado'; RETURN nuevo_estado;
END $$;
REVOKE ALL ON FUNCTION public.revisar_documento_ep_subcontrato(BIGINT,TEXT,TEXT) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.revisar_documento_ep_subcontrato(BIGINT,TEXT,TEXT) TO authenticated;
REVOKE ALL ON FUNCTION public.aprobar_ep_subcontrato_y_cargar_costo(BIGINT,TEXT) FROM PUBLIC,anon;

CREATE INDEX IF NOT EXISTS idx_sub_ep_docs_ep ON public.subcontrato_ep_documentos(estado_pago_id);
CREATE INDEX IF NOT EXISTS idx_sub_ep_docs_req ON public.subcontrato_ep_documentos(requisito_id);
CREATE INDEX IF NOT EXISTS idx_sub_ep_hist_ep ON public.subcontrato_ep_historial(estado_pago_id);
CREATE INDEX IF NOT EXISTS idx_sub_ep_hist_doc ON public.subcontrato_ep_historial(documento_id);
